1	/**
2	 * @file lvgl_init.c
3	 * @brief LVGL 初始化实现
4	 *
5	 * 初始化 LVGL 库，注册 CO5300 AMOLED 显示驱动。
6	 * 使用双缓冲 + DMA 刷新策略，适配黄山派 SF32LB52 平台。
7	 *
8	 * 2026 OpenVela AI 硬件开发者大赛 - team329
9	 */
10	
11	#include <nuttx/config.h>
12	#include <stdio.h>
13	#include <string.h>
14	#include <unistd.h>
15	
16	#include "lvgl.h"
