18	
19	/****************************************************************************
20	 * Pre-processor Definitions
21	 ****************************************************************************/
22	
23	/* 显示缓冲区大小 */
24	#define DISP_BUF_SIZE   (LCD_WIDTH * LCD_BUF_LINES)
25	
26	/****************************************************************************
27	 * Private Data
28	 ****************************************************************************/
29	
30	static bool g_lvgl_initialized = false;
31	
32	/* LVGL 显示缓冲区 */
33	static lv_color_t g_disp_buf1[DISP_BUF_SIZE];
34	static lv_color_t g_disp_buf2[DISP_BUF_SIZE];
35	
36	/****************************************************************************
37	 * Private Functions
38	 ****************************************************************************/
39	
40	/**
41	 * @brief LCD 刷新回调
42	 *
43	 * LVGL 调用此函数将帧缓冲区内容刷新到 CO5300 LCD。
44	 * 使用 SiFli LCD 驱动接口进行区域刷新。
45	 *
46	 * @param drv 显示驱动指针
47	 * @param area 刷新区域
48	 * @param color_p 像素数据
49	 */
50	static void lcd_flush_cb(lv_display_t *drv, const lv_area_t *area,
51	                          lv_color_t *color_p)
52	{
53	    /* 计算区域参数 */
54	    int32_t x1 = area->x1;
55	    int32_t y1 = area->y1;
56	    int32_t x2 = area->x2;
57	    int32_t y2 = area->y2;
58	    int32_t w = x2 - x1 + 1;
59	    int32_t h = y2 - y1 + 1;
60	
61	    /* TODO: 调用 SiFli LCD 驱动刷新
62	     * 例如:
63	     *   BSP_LCD_SetWindow(x1, y1, x2, y2);
64	     *   BSP_LCD_WriteDataDMA((uint8_t *)color_p, w * h * 2);
65	     */
66	
67	    /* 标记刷新完成 */
68	    lv_display_flush_ready(drv);
69	}
