71	/**
72	 * @brief LCD 初始化
73	 *
74	 * 初始化 CO5300 AMOLED 显示屏硬件。
75	 *
76	 * @return 0 成功，负数失败
77	 */
78	static int lcd_hw_init(void)
79	{
80	    /* CO5300 AMOLED 初始化序列
81	     * - SPI 配置: 4-wire, 高速模式
82	     * - 分辨率: 390x450
83	     * - 色深: 16-bit RGB565
84	     * - 帧率: 60Hz
85	     */
86	
87	    /* TODO: 实现 CO5300 硬件初始化
88	     * 1. 复位 LCD (BSP_LCD_Reset)
89	     * 2. 发送初始化命令序列
90	     * 3. 设置显示方向和窗口
91	     * 4. 开启显示
92	     */
93	
94	    printf("[LVGL] LCD hardware initialized (CO5300 %dx%d)\n",
95	           LCD_WIDTH, LCD_HEIGHT);
96	    return 0;
97	}
98	
99	/****************************************************************************
100	 * Public Functions
101	 ****************************************************************************/
102	
103	int lvgl_init(void)
104	{
105	    int ret;
106	
107	    if (g_lvgl_initialized)
108	    {
109	        printf("[LVGL] Already initialized\n");
110	        return 0;
111	    }
112	
113	    /* 步骤1: 初始化 LVGL 库 */
114	    lv_init();
115	    printf("[LVGL] lv_init() done\n");
116	
117	    /* 步骤2: 初始化 LCD 硬件 */
118	    ret = lcd_hw_init();
119	    if (ret < 0)
120	    {
121	        printf("[LVGL] LCD hardware init failed: %d\n", ret);
122	        return ret;
123	    }
124	
125	    /* 步骤3: 创建显示驱动 */
126	    lv_display_t *disp = lv_display_create(LCD_WIDTH, LCD_HEIGHT);
127	    if (disp == NULL)
128	    {
129	        printf("[LVGL] Failed to create display\n");
130	        return -1;
131	    }
132	
133	    /* 步骤4: 设置双缓冲区 */
134	    lv_display_set_flush_cb(disp, lcd_flush_cb);
135	    lv_display_set_buffers(disp, g_disp_buf1, g_disp_buf2,
136	                           sizeof(g_disp_buf1),
137	                           LV_DISPLAY_RENDER_MODE_PARTIAL);
138	
139	    /* 步骤5: 设置为默认屏幕 */
140	    lv_display_set_default(disp);
141	
142	    g_lvgl_initialized = true;
143	    printf("[LVGL] Initialization complete (%dx%d, %d-bit)\n",
144	           LCD_WIDTH, LCD_HEIGHT, LCD_COLOR_DEPTH);
145	
146	    return 0;
147	}
148	
149	bool lvgl_is_initialized(void)
150	{
151	    return g_lvgl_initialized;
152	}
153	
154	void lvgl_deinit(void)
155	{
156	    if (!g_lvgl_initialized)
157	    {
158	        return;
159	    }
160	
161	    lv_deinit();
162	    g_lvgl_initialized = false;
163	    printf("[LVGL] Deinitialized\n");
164	}
