224	void watchface_update(const watchface_data_t *data)
225	{
226	    if (data == NULL || g_watchface == NULL)
227	    {
228	        return;
229	    }
230	
231	    /* 更新时间 (HH:MM:SS 格式) */
232	    char time_str[16];
233	    snprintf(time_str, sizeof(time_str), "%02d:%02d:%02d",
234	             data->hour, data->minute, data->second);
235	    lv_label_set_text(g_time_label, time_str);
236	
237	    /* 更新日期 */
238	    char date_str[32];
239	    snprintf(date_str, sizeof(date_str), "%04d-%02d-%02d %s",
240	             data->year, data->month, data->day,
241	             watchface_get_weekday_str(data->weekday));
242	    lv_label_set_text(g_date_label, date_str);
243	
244	    /* 更新活动状态 */
245	    if (data->activity_icon != NULL)
246	    {
247	        lv_label_set_text(g_activity_icon, data->activity_icon);
248	    }
249	    if (data->activity_text != NULL)
250	    {
251	        lv_label_set_text(g_activity_text, data->activity_text);
252	    }
253	
254	    /* 根据活动状态设置颜色 */
255	    lv_color_t state_color;
256	    if (data->activity_text != NULL)
257	    {
258	        if (strcmp(data->activity_text, "Sitting") == 0)
259	        {
260	            state_color = COLOR_GREEN;
261	        }
262	        else if (strcmp(data->activity_text, "Walking") == 0)
263	        {
264	            state_color = COLOR_ACCENT;
265	        }
266	        else if (strcmp(data->activity_text, "Running") == 0)
267	        {
268	            state_color = COLOR_ORANGE;
269	        }
270	        else
271	        {
272	            state_color = COLOR_GRAY;
273	        }
274	        lv_obj_set_style_text_color(g_activity_icon, state_color, LV_PART_MAIN);
275	    }
276	
277	    /* 更新步数 */
278	    char steps_str[32];
279	    snprintf(steps_str, sizeof(steps_str), LV_SYMBOL_WALK " %lu steps",
280	             (unsigned long)data->steps);
281	    lv_label_set_text(g_steps_label, steps_str);
282	
283	    /* 更新 Agent 状态灯 */
284	    lv_color_t agent_color;
285	    switch (data->agent_status)
286	    {
287	        case AGENT_STATUS_IDLE:
288	            agent_color = COLOR_GREEN;
289	            break;
290	        case AGENT_STATUS_THINKING:
291	            agent_color = COLOR_ACCENT;
292	            break;
293	        case AGENT_STATUS_EXECUTING:
294	            agent_color = COLOR_ORANGE;
295	            break;
296	        case AGENT_STATUS_OFFLINE:
297	        default:
298	            agent_color = COLOR_GRAY;
299	            break;
300	    }
301	    lv_obj_set_style_bg_color(g_agent_indicator, agent_color, LV_PART_MAIN);
302	
303	    /* 更新电量 */
304	    char battery_str[16];
305	    const char *battery_icon;
306	    if (data->battery_percent > 80)
307	    {
308	        battery_icon = LV_SYMBOL_BATTERY_FULL;
309	    }
310	    else if (data->battery_percent > 50)
311	    {
312	        battery_icon = LV_SYMBOL_BATTERY_3;
313	    }
314	    else if (data->battery_percent > 20)
315	    {
316	        battery_icon = LV_SYMBOL_BATTERY_2;
317	    }
318	    else
319	    {
320	        battery_icon = LV_SYMBOL_BATTERY_1;
321	    }
322	    snprintf(battery_str, sizeof(battery_str), "%s %d%%",
323	             battery_icon, data->battery_percent);
324	    lv_label_set_text(g_battery_label, battery_str);
325	}
