377	/**
378	 * @brief 定时器回调 - 每秒刷新时间和日期
379	 */
380	static void refresh_timer_cb(lv_timer_t *timer)
381	{
382	    if (g_time_label == NULL || g_date_label == NULL)
383	    {
384	        return;
385	    }
386	
387	    /* 获取当前时间 */
388	    time_t now = time(NULL);
389	    struct tm *tm = localtime(&now);
390	
391	    /* 更新时间 (HH:MM:SS) */
392	    char time_str[16];
393	    snprintf(time_str, sizeof(time_str), "%02d:%02d:%02d",
394	             tm->tm_hour, tm->tm_min, tm->tm_sec);
395	    lv_label_set_text(g_time_label, time_str);
396	
397	    /* 更新日期 (YYYY-MM-DD Weekday) */
398	    char date_str[32];
399	    snprintf(date_str, sizeof(date_str), "%04d-%02d-%02d %s",
400	             tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
401	             watchface_get_weekday_str(tm->tm_wday));
402	    lv_label_set_text(g_date_label, date_str);
403	}
404	
405	int watchface_start_timer(void)
406	{
407	    if (g_refresh_timer != NULL)
408	    {
409	        printf("[UI] Refresh timer already running\n");
410	        return 0;
411	    }
412	
413	    /* 创建 1 秒周期定时器 */
414	    g_refresh_timer = lv_timer_create(refresh_timer_cb, 1000, NULL);
415	    if (g_refresh_timer == NULL)
416	    {
417	        printf("[UI] Failed to create refresh timer\n");
418	        return -1;
419	    }
420	
