128	/**
129	 * @brief 任务项点击回调
130	 */
131	static void task_item_click_cb(lv_event_t *e)
132	{
133	    lv_obj_t *btn = lv_event_get_target(e);
134	    int task_id = (int)(intptr_t)lv_event_get_user_data(e);
135	
136	    /* 查找任务 */
137	    for (int i = 0; i < g_task_data.count; i++)
138	    {
139	        if (g_task_data.items[i].id == task_id)
140	        {
141	            g_selected_task_id = task_id;
142	
143	            /* 更新详情弹窗 */
144	            if (g_detail_title != NULL)
145	            {
146	                lv_label_set_text(g_detail_title,
147	                                   g_task_data.items[i].title);
148	            }
149	
150	            if (g_detail_desc != NULL)
151	            {
152	                lv_label_set_text(g_detail_desc,
153	                                   g_task_data.items[i].description);
154	            }
155	
156	            if (g_detail_time != NULL)
157	            {
158	                char time_str[16];
159	                snprintf(time_str, sizeof(time_str), "%02d:%02d",
160	                         g_task_data.items[i].hour,
161	                         g_task_data.items[i].minute);
162	                lv_label_set_text(g_detail_time, time_str);
163	            }
164	
165	            if (g_detail_status != NULL)
166	            {
167	                lv_label_set_text(g_detail_status,
168	                                   get_status_text(g_task_data.items[i].status));
169	                lv_obj_set_style_text_color(g_detail_status,
170	                    get_status_color(g_task_data.items[i].status),
171	                    LV_PART_MAIN);
172	            }
173	
174	            /* 显示弹窗 */
175	            if (g_detail_popup != NULL)
176	            {
177	                lv_obj_clear_flag(g_detail_popup, LV_OBJ_FLAG_HIDDEN);
178	            }
179	
180	            break;
181	        }
182	    }
183	}
