426	/**
427	 * @brief 重建列表 UI
428	 */
429	static void rebuild_list(void)
430	{
431	    if (g_list_widget == NULL)
432	    {
433	        return;
434	    }
435	
436	    /* 清空列表 */
437	    lv_obj_clean(g_list_widget);
438	
439	    /* 更新标题 */
440	    if (g_title_label != NULL)
441	    {
442	        char title_str[32];
443	        snprintf(title_str, sizeof(title_str), LV_SYMBOL_LIST " Tasks (%d)",
444	                 g_task_data.count);
445	        lv_label_set_text(g_title_label, title_str);
446	    }
447	
448	    if (g_task_data.count == 0)
449	    {
450	        /* 显示空列表提示 */
451	        if (g_empty_label != NULL)
452	        {
453	            lv_obj_clear_flag(g_empty_label, LV_OBJ_FLAG_HIDDEN);
454	        }
455	        return;
456	    }
457	
458	    /* 隐藏空列表提示 */
459	    if (g_empty_label != NULL)
460	    {
461	        lv_obj_add_flag(g_empty_label, LV_OBJ_FLAG_HIDDEN);
462	    }
463	
464	    /* 创建任务项 */
465	    for (int i = 0; i < g_task_data.count; i++)
466	    {
467	        create_task_item_ui(g_list_widget, &g_task_data.items[i]);
468	    }
469	}
