556	void task_list_refresh(const task_list_t *data)
557	{
558	    if (data == NULL)
559	    {
560	        return;
561	    }
562	
563	    /* 复制数据 */
564	    int count = data->count;
565	    if (count > TASK_MAX_COUNT)
566	    {
567	        count = TASK_MAX_COUNT;
568	    }
569	
570	    memcpy(&g_task_data, data, sizeof(task_list_t));
571	    g_task_data.count = count;
572	
573	    /* 重建列表 */
574	    rebuild_list();
575	
576	    printf("[TASK] List refreshed: %d tasks\n", count);
577	}
