579	int task_list_add_item(const task_item_t *item)
580	{
581	    if (item == NULL)
582	    {
583	        return -1;
584	    }
585	
586	    if (g_task_data.count >= TASK_MAX_COUNT)
587	    {
588	        printf("[TASK] Task list full\n");
589	        return -1;
590	    }
591	
592	    /* 复制任务 */
593	    memcpy(&g_task_data.items[g_task_data.count], item, sizeof(task_item_t));
594	    g_task_data.count++;
595	
596	    /* 重建列表 */
597	    rebuild_list();
598	
599	    return 0;
600	}
