602	int task_list_delete_item(int task_id)
603	{
604	    int found = -1;
605	
606	    for (int i = 0; i < g_task_data.count; i++)
607	    {
608	        if (g_task_data.items[i].id == task_id)
609	        {
610	            found = i;
611	            break;
612	        }
613	    }
614	
615	    if (found < 0)
616	    {
617	        printf("[TASK] Task %d not found\n", task_id);
618	        return -1;
619	    }
620	
621	    /* 移除任务（前移后续元素） */
622	    for (int i = found; i < g_task_data.count - 1; i++)
623	    {
624	        memcpy(&g_task_data.items[i], &g_task_data.items[i + 1],
625	               sizeof(task_item_t));
626	    }
627	    g_task_data.count--;
628	
629	    /* 重建列表 */
630	    rebuild_list();
631	
632	    printf("[TASK] Task %d deleted\n", task_id);
633	    return 0;
634	}
