636	int task_list_complete_item(int task_id)
637	{
638	    for (int i = 0; i < g_task_data.count; i++)
639	    {
640	        if (g_task_data.items[i].id == task_id)
641	        {
642	            g_task_data.items[i].status = TASK_STATUS_COMPLETED;
643	            rebuild_list();
644	            printf("[TASK] Task %d completed\n", task_id);
645	            return 0;
646	        }
647	    }
648	
649	    printf("[TASK] Task %d not found\n", task_id);
650	    return -1;
651	}
