136	/**
137	 * @brief 更新旋转动画
138	 *
139	 * 每帧更新各点的角度位置，实现旋转效果。
140	 * 从 0 度开始，每帧旋转 45 度 (360/8)。
141	 */
142	static void update_spin_animation(void)
143	{
144	    int frame = g_icon_ctx.anim_frame;
145	
146	    for (int i = 0; i < SPIN_DOT_COUNT; i++)
147	    {
148	        if (g_icon_ctx.dots[i] == NULL)
149	        {
150	            continue;
151	        }
152	
153	        /* 计算角度: 基础角度 + 帧偏移 */
154	        float angle = (float)(i * 360 / SPIN_DOT_COUNT + frame * 45)
155	                      * 3.14159f / 180.0f;
156	
157	        /* 计算坐标 (相对于容器中心) */
158	        int cx = (int)(SPIN_DOT_RADIUS * cosf(angle));
159	        int cy = (int)(SPIN_DOT_RADIUS * sinf(angle));
160	
161	        /* 设置透明度: 当前点最亮，其余递减 */
162	        int alpha_idx = (i - frame % SPIN_DOT_COUNT + SPIN_DOT_COUNT)
163	                        % SPIN_DOT_COUNT;
164	        lv_opa_t opa = (alpha_idx == 0) ? LV_OPA_COVER :
165	                       (alpha_idx == 1) ? LV_OPA_70 :
166	                       (alpha_idx == 2) ? LV_OPA_40 : LV_OPA_20;
167	
168	        lv_obj_set_style_bg_opa(g_icon_ctx.dots[i], opa, LV_PART_MAIN);
169	        lv_obj_align(g_icon_ctx.dots[i], LV_ALIGN_CENTER, cx, cy);
170	    }
171	}
172	
173	/**
174	 * @brief 动画定时器回调
175	 */
176	static void anim_timer_cb(lv_timer_t *timer)
177	{
178	    switch (g_icon_ctx.current_state)
179	    {
180	        case ICON_STATE_THINKING:
181	            update_spin_animation();
182	            g_icon_ctx.anim_frame++;
183	            break;
184	
185	        case ICON_STATE_EXECUTING:
186	            /* 进度条由外部设置，定时器用于动画刷新 */
187	            break;
188	
189	        default:
190	            break;
191	    }
192	}
