198	int icon_anim_init(lv_obj_t *parent, int x, int y)
199	{
200	    int ret;
201	
202	    if (g_icon_ctx.initialized)
203	    {
204	        printf("[ICONS] Already initialized\n");
205	        return 0;
206	    }
207	
208	    memset(&g_icon_ctx, 0, sizeof(icon_anim_ctx_t));
209	
210	    /* 创建容器 */
211	    g_icon_ctx.container = lv_obj_create(parent);
212	    if (g_icon_ctx.container == NULL)
213	    {
214	        printf("[ICONS] Failed to create container\n");
215	        return -1;
216	    }
217	
218	    lv_obj_set_size(g_icon_ctx.container, ICON_SIZE + 10, ICON_SIZE + 10);
219	    lv_obj_set_style_bg_color(g_icon_ctx.container, COLOR_BG, LV_PART_MAIN);
220	    lv_obj_set_style_bg_opa(g_icon_ctx.container, LV_OPA_TRANSP,
221	                             LV_PART_MAIN);
222	    lv_obj_set_style_border_width(g_icon_ctx.container, 0, LV_PART_MAIN);
223	    lv_obj_set_style_pad_all(g_icon_ctx.container, 0, LV_PART_MAIN);
224	    lv_obj_align(g_icon_ctx.container, LV_ALIGN_CENTER, x, y);
225	
226	    /* 创建空闲图标 */
227	    ret = create_idle_icon(g_icon_ctx.container);
228	    if (ret < 0)
229	    {
230	        return ret;
231	    }
232	
233	    /* 创建旋转点 */
234	    ret = create_spin_dots(g_icon_ctx.container);
235	    if (ret < 0)
236	    {
237	        return ret;
238	    }
239	
240	    /* 创建进度条 */
241	    ret = create_progress_bar(g_icon_ctx.container);
242	    if (ret < 0)
243	    {
244	        return ret;
245	    }
246	
247	    /* 创建动画定时器 */
248	    g_icon_ctx.anim_timer = lv_timer_create(anim_timer_cb,
249	                                             1000 / ICON_ANIM_FPS, NULL);
250	    if (g_icon_ctx.anim_timer == NULL)
251	    {
252	        printf("[ICONS] Failed to create anim timer\n");
253	        return -1;
254	    }
255	
256	    lv_timer_set_repeat_count(g_icon_ctx.anim_timer, -1);
257	
258	    /* 默认显示空闲状态 */
259	    g_icon_ctx.current_state = ICON_STATE_IDLE;
260	    g_icon_ctx.initialized = true;
261	
262	    printf("[ICONS] Icon animation initialized\n");
263	    return 0;
264	}
