266	void icon_anim_set_state(int state)
267	{
268	    if (!g_icon_ctx.initialized)
269	    {
270	        return;
271	    }
272	
273	    if (state == g_icon_ctx.current_state)
274	    {
275	        return;
276	    }
277	
278	    /* 隐藏所有元素 */
279	    hide_all_elements();
280	
281	    /* 切换状态 */
282	    g_icon_ctx.current_state = state;
283	    g_icon_ctx.anim_frame = 0;
284	
285	    switch (state)
286	    {
287	        case ICON_STATE_IDLE:
288	            if (g_icon_ctx.idle_icon != NULL)
289	            {
290	                lv_obj_clear_flag(g_icon_ctx.idle_icon, LV_OBJ_FLAG_HIDDEN);
291	                lv_obj_set_style_text_color(g_icon_ctx.idle_icon,
292	                                             COLOR_IDLE, LV_PART_MAIN);
293	            }
294	            break;
295	
296	        case ICON_STATE_THINKING:
297	            for (int i = 0; i < SPIN_DOT_COUNT; i++)
298	            {
299	                if (g_icon_ctx.dots[i] != NULL)
300	                {
301	                    lv_obj_clear_flag(g_icon_ctx.dots[i], LV_OBJ_FLAG_HIDDEN);
302	                    lv_obj_set_style_bg_color(g_icon_ctx.dots[i],
303	                                               COLOR_THINKING, LV_PART_MAIN);
304	                }
305	            }
306	            break;
307	
308	        case ICON_STATE_EXECUTING:
309	            if (g_icon_ctx.progress_bar != NULL)
310	            {
311	                lv_obj_clear_flag(g_icon_ctx.progress_bar, LV_OBJ_FLAG_HIDDEN);
312	                lv_bar_set_value(g_icon_ctx.progress_bar, 0, LV_ANIM_OFF);
313	            }
314	            break;
315	
316	        case ICON_STATE_OFFLINE:
317	            if (g_icon_ctx.idle_icon != NULL)
318	            {
319	                lv_obj_clear_flag(g_icon_ctx.idle_icon, LV_OBJ_FLAG_HIDDEN);
320	                lv_obj_set_style_text_color(g_icon_ctx.idle_icon,
321	                                             COLOR_OFFLINE, LV_PART_MAIN);
322	            }
323	            break;
324	
325	        default:
326	            break;
327	    }
328	
329	    printf("[ICONS] State changed to %d\n", state);
330	}
