8	 * 2026 OpenVela AI 硬件开发者大赛 - team329
9	 */
10	
11	#include <nuttx/config.h>
12	#include <stdio.h>
13	#include <stdlib.h>
14	#include <string.h>
15	#include <time.h>
16	
17	#include "lvgl.h"
18	#include "gesture.h"
19	
20	/****************************************************************************
21	 * Private Data
22	 ****************************************************************************/
23	
24	static gesture_ctx_t g_gesture_ctx;
25	static bool g_gesture_ready = false;
26	
27	/****************************************************************************
28	 * Private Functions
29	 ****************************************************************************/
30	
31	/**
32	 * @brief 获取当前时间 (毫秒)
33	 */
34	static int get_time_ms(void)
35	{
36	    struct timespec ts;
37	    clock_gettime(CLOCK_MONOTONIC, &ts);
38	    return (int)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
39	}
40	
41	/**
42	 * @brief 判断手势方向
43	 *
44	 * 根据起止点的水平/垂直位移判断主方向。
45	 * 对角线滑动取位移较大的方向。
46	 *
47	 * @param dx 水平位移
48	 * @param dy 垂直位移
49	 * @return 手势方向
50	 */
51	static int determine_gesture(int dx, int dy)
52	{
53	    int abs_dx = abs(dx);
54	    int abs_dy = abs(dy);
55	
56	    /* 位移不足 */
57	    if (abs_dx < GESTURE_MIN_DISTANCE && abs_dy < GESTURE_MIN_DISTANCE)
58	    {
59	        return GESTURE_TYPE_NONE;
60	    }
61	
62	    /* 对角线：取位移大的方向 */
63	    if (abs_dx > abs_dy)
64	    {
65	        /* 水平滑动 */
66	        return (dx < 0) ? GESTURE_TYPE_LEFT : GESTURE_TYPE_RIGHT;
67	    }
68	    else
69	    {
70	        /* 垂直滑动 */
71	        return (dy < 0) ? GESTURE_TYPE_UP : GESTURE_TYPE_DOWN;
72	    }
73	}
74	
75	/**
76	 * @brief 触发手势事件
77	 */
78	static void fire_gesture(int gesture)
79	{
80	    if (gesture == GESTURE_TYPE_NONE)
81	    {
82	        return;
83	    }
84	
85	    printf("[GESTURE] Detected: %s\n",
86	           gesture == GESTURE_TYPE_LEFT ? "LEFT" :
87	           gesture == GESTURE_TYPE_RIGHT ? "RIGHT" :
88	           gesture == GESTURE_TYPE_UP ? "UP" :
89	           gesture == GESTURE_TYPE_DOWN ? "DOWN" : "???");
90	
91	    /* 调用回调 */
92	    if (g_gesture_ctx.callback != NULL)
93	    {
94	        g_gesture_ctx.callback(gesture);
95	    }
96	}
97	
98	/****************************************************************************
99	 * Public Functions
100	 ****************************************************************************/
101	
102	int gesture_init(void)
103	{
104	    if (g_gesture_ready)
105	    {
106	        printf("[GESTURE] Already initialized\n");
107	        return 0;
108	    }
109	
110	    memset(&g_gesture_ctx, 0, sizeof(gesture_ctx_t));
111	    g_gesture_ready = true;
112	
113	    printf("[GESTURE] Gesture detector initialized\n");
114	    printf("[GESTURE] Threshold: %dpx, Max duration: %dms\n",
115	           GESTURE_MIN_DISTANCE, GESTURE_MAX_DURATION);
116	    return 0;
117	}
118	
119	void gesture_set_callback(gesture_cb_t cb)
120	{
121	    g_gesture_ctx.callback = cb;
122	}
123	
124	void gesture_process(int x, int y, bool pressed)
125	{
126	    if (!g_gesture_ready)
127	    {
128	        return;
129	    }
130	
131	    int now = get_time_ms();
132	
133	    if (pressed)
134	    {
135	        /* 按下事件 */
136	        if (!g_gesture_ctx.tracking && !g_gesture_ctx.locked)
137	        {
138	            /* 开始跟踪 */
139	            g_gesture_ctx.tracking = true;
140	            g_gesture_ctx.start_x = x;
141	            g_gesture_ctx.start_y = y;
142	            g_gesture_ctx.start_time = now;
143	        }
144	        else if (g_gesture_ctx.tracking)
145	        {
146	            /* 持续跟踪，检查超时 */
147	            int elapsed = now - g_gesture_ctx.start_time;
148	            if (elapsed > GESTURE_MAX_DURATION)
149	            {
150	                /* 超时取消 */
151	                g_gesture_ctx.tracking = false;
152	            }
153	        }
154	    }
155	    else
156	    {
157	        /* 释放事件 */
158	        if (g_gesture_ctx.tracking)
159	        {
160	            /* 计算位移 */
161	            int dx = x - g_gesture_ctx.start_x;
162	            int dy = y - g_gesture_ctx.start_y;
163	            int elapsed = now - g_gesture_ctx.start_time;
164	
165	            /* 时间检查 */
166	            if (elapsed <= GESTURE_MAX_DURATION)
167	            {
168	                int gesture = determine_gesture(dx, dy);
169	                if (gesture != GESTURE_TYPE_NONE)
170	                {
171	                    /* 触发手势 */
172	                    fire_gesture(gesture);
173	
174	                    /* 锁定防止重复触发 */
175	                    g_gesture_ctx.locked = true;
176	                    g_gesture_ctx.lock_time = now;
177	                }
178	            }
179	
180	            g_gesture_ctx.tracking = false;
181	        }
182	
183	        /* 检查锁定超时 */
184	        if (g_gesture_ctx.locked)
185	        {
186	            if (now - g_gesture_ctx.lock_time >= GESTURE_LOCK_TIME)
187	            {
188	                g_gesture_ctx.locked = false;
189	            }
190	        }
191	    }
192	}
193	
194	bool gesture_is_ready(void)
195	{
196	    return g_gesture_ready;
197	}
198	
199	void gesture_deinit(void)
200	{
201	    g_gesture_ready = false;
202	    memset(&g_gesture_ctx, 0, sizeof(gesture_ctx_t));
203	    printf("[GESTURE] Gesture detector deinitialized\n");
204	}
