1	/**
2	 * @file touch_input.c
3	 * @brief 触摸输入驱动实现
4	 *
5	 * 注册触摸屏作为 LVGL 输入设备，处理触摸事件。
6	 * 支持按下、释放和滑动手势检测。
7	 *
8	 * 2026 OpenVela AI 硬件开发者大赛 - team329
9	 */
10	
11	#include <nuttx/config.h>
12	#include <stdio.h>
13	#include <string.h>
14	#include <fcntl.h>
15	#include <unistd.h>
16	#include <sys/ioctl.h>
17	
18	#include "lvgl.h"
19	#include "touch_input.h"
20	
21	/****************************************************************************
22	 * Pre-processor Definitions
23	 ****************************************************************************/
24	
25	/* NuttX 触摸屏事件结构 */
26	struct touch_event_s
27	{
28	    int x;              /* X 坐标 */
29	    int y;              /* Y 坐标 */
30	    int timestamp;      /* 时间戳 */
31	    int action;         /* 0=释放, 1=按下 */
32	};
33	
34	/* NuttX 触摸屏 ioctl 命令 */
35	#ifndef TSIOC_SETEVENT
36	    #define TSIOC_SETEVENT  _TSIOC(0x0002)
37	#endif
38	
39	/****************************************************************************
40	 * Private Data
41	 ****************************************************************************/
42	
43	static bool g_touch_ready = false;
44	static int g_touch_fd = -1;
45	
46	/* LVGL 输入设备 */
47	static lv_indev_t *g_touch_indev = NULL;
48	
49	/* 触摸状态 */
50	static int g_last_x = 0;
51	static int g_last_y = 0;
52	static bool g_pressed = false;
53	
54	/* 滑动检测 */
55	static int g_swipe_start_x = 0;
56	static int g_swipe_start_y = 0;
57	static int g_swipe_start_time = 0;
58	static bool g_swipe_tracking = false;
59	
60	/****************************************************************************
61	 * Private Functions
62	 ****************************************************************************/
63	
64	/**
65	 * @brief 从触摸屏设备读取数据
66	 *
67	 * @param data 输出触摸数据
68	 * @return 0 成功，负数失败
69	 */
70	static int read_touch_data(int *x, int *y, bool *pressed)
71	{
72	    if (g_touch_fd < 0)
73	    {
74	        return -1;
75	    }
76	
77	    struct touch_event_s event;
78	    int ret = read(g_touch_fd, &event, sizeof(event));
79	    if (ret < sizeof(event))
80	    {
81	        return -1;
82	    }
83	
84	    *x = event.x;
85	    *y = event.y;
86	    *pressed = (event.action == 1);
87	
88	    return 0;
89	}
90	
91	/**
92	 * @brief LVGL 触摸读取回调
93	 *
94	 * LVGL 定期调用此函数获取触摸状态。
95	 *
96	 * @param indev 输入设备
97	 * @param data 输出数据
98	 */
99	static void touch_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
100	{
101	    int x, y;
102	    bool pressed;
103	
104	    int ret = read_touch_data(&x, &y, &pressed);
105	    if (ret < 0)
106	    {
107	        /* 无新数据，保持上次状态 */
108	        data->point.x = g_last_x;
109	        data->point.y = g_last_y;
110	        data->state = g_pressed ? LV_INDEV_STATE_PRESSED
111	                                : LV_INDEV_STATE_RELEASED;
112	        return;
113	    }
114	
115	    g_last_x = x;
116	    g_last_y = y;
117	    g_pressed = pressed;
118	
119	    data->point.x = x;
120	    data->point.y = y;
121	    data->state = pressed ? LV_INDEV_STATE_PRESSED
122	                          : LV_INDEV_STATE_RELEASED;
123	}
124	
125	/**
126	 * @brief 触摸屏硬件初始化
127	 *
128	 * 打开 NuttX 触摸屏字符设备。
129	 *
130	 * @return 0 成功，负数失败
131	 */
132	static int touch_hw_init(void)
133	{
134	    /* 打开触摸屏设备 */
135	    g_touch_fd = open(TOUCH_DEV_PATH, O_RDONLY);
136	    if (g_touch_fd < 0)
137	    {
138	        printf("[TOUCH] Failed to open %s\n", TOUCH_DEV_PATH);
139	        return -1;
140	    }
141	
142	    printf("[TOUCH] Touch device opened: %s\n", TOUCH_DEV_PATH);
143	    return 0;
144	}
145	
146	/****************************************************************************
147	 * Public Functions
148	 ****************************************************************************/
149	
150	int touch_input_init(void)
151	{
152	    int ret;
153	
154	    if (g_touch_ready)
155	    {
156	        printf("[TOUCH] Already initialized\n");
157	        return 0;
158	    }
159	
160	    /* 初始化触摸屏硬件 */
161	    ret = touch_hw_init();
162	    if (ret < 0)
163	    {
164	        printf("[TOUCH] Touch hardware init failed: %d\n", ret);
165	        return ret;
166	    }
167	
168	    /* 注册 LVGL 输入设备 */
169	    g_touch_indev = lv_indev_create();
170	    if (g_touch_indev == NULL)
171	    {
172	        printf("[TOUCH] Failed to create input device\n");
173	        close(g_touch_fd);
174	        g_touch_fd = -1;
175	        return -1;
176	    }
177	
178	    lv_indev_set_type(g_touch_indev, LV_INDEV_TYPE_POINTER);
179	    lv_indev_set_read_cb(g_touch_indev, touch_read_cb);
180	    lv_indev_set_name(g_touch_indev, "touchpad");
181	
182	    g_touch_ready = true;
183	    printf("[TOUCH] Touch input registered to LVGL\n");
184	
185	    return 0;
186	}
187	
188	void touch_input_deinit(void)
189	{
190	    if (!g_touch_ready)
191	    {
192	        return;
193	    }
194	
195	    if (g_touch_fd >= 0)
196	    {
197	        close(g_touch_fd);
198	        g_touch_fd = -1;
199	    }
200	
201	    g_touch_ready = false;
202	    printf("[TOUCH] Touch input deinitialized\n");
203	}
204	
205	bool touch_input_is_ready(void)
206	{
207	    return g_touch_ready;
208	}
