45	/**
46	 * @brief 初始化传感器
47	 */
48	static int init_sensors(void)
49	{
50	    int ret;
51	
52	    printf("[INIT] Initializing activity detector...\n");
53	    activity_detector_init(&g_detector);
54	
55	    printf("[INIT] Initializing IMU monitor...\n");
56	    ret = imu_monitor_init(&g_imu);
57	    if (ret < 0)
58	    {
59	        printf("[INIT] Warning: IMU init failed: %d\n", ret);
60	        printf("[INIT] Running in demo mode\n");
61	        return ret;
62	    }
