64	    ret = imu_monitor_start(&g_imu);
65	    if (ret < 0)
66	    {
67	        printf("[INIT] Warning: IMU start failed: %d\n", ret);
68	        return ret;
69	    }
70	
71	    /* 读取芯片信息 */
72	    uint8_t chip_id;
73	    char chip_name[32];
74	    ret = imu_monitor_get_chip_info(&chip_id, chip_name);
