98	        {
99	            /* 输入到活动检测器 */
100	            bool ready = activity_detector_input(&g_detector,
101	                                                 imu_data.accel_x,
102	                                                 imu_data.accel_y,
103	                                                 imu_data.accel_z);
104	
105	            /* 窗口已满，获取结果 */
106	            if (ready)
