/**
 * @file uart_echo_test.c
 * @brief 最小串口回显测试
 *
 * 用途：验证串口通信正常，确认硬件基本可用
 * 编译：在 NSH 配置下直接编译
 * 使用：烧录后在串口终端输入字符，应原样回显
 */

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/**
 * @brief 主函数 - 串口回显测试
 *
 * 功能：
 * 1. 打印启动信息
 * 2. 读取串口输入
 * 3. 回显输入内容
 * 4. 循环运行
 */
int main(int argc, char *argv[])
{
    char buf[128];
    int count = 0;

    printf("\n");
    printf("========================================\n");
    printf("  UART Echo Test - VelaWear\n");
    printf("  Board: SF32LB52 HuangShan Pi\n");
    printf("========================================\n");
    printf("Type something and it will be echoed back.\n");
    printf("Type 'quit' to exit.\n");
    printf("\n");

    while (1)
    {
        printf("[%d] > ", ++count);
        fflush(stdout);

        /* 读取一行输入 */
        if (fgets(buf, sizeof(buf), stdin) != NULL)
        {
            /* 去掉换行符 */
            size_t len = strlen(buf);
            if (len > 0 && buf[len - 1] == '\n')
            {
                buf[len - 1] = '\0';
            }

            /* 检查退出命令 */
            if (strcmp(buf, "quit") == 0)
            {
                printf("Bye!\n");
                break;
            }

            /* 回显 */
            printf("Echo: %s\n", buf);
            printf("Length: %zu bytes\n", strlen(buf));
        }
        else
        {
            printf("Read error, retrying...\n");
            usleep(100000);  /* 100ms */
        }
    }

    return 0;
}

